<?php
declare(strict_types=1);require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/auth.php';require_once __DIR__.'/../../src/ui.php';$user=require_student();$pdo=db();$stmt=$pdo->prepare("SELECT v.word,v.translation,v.definition_en,v.example,v.level,v.category,sv.status,sv.mastery_score,sv.repetitions,sv.correct_answers,sv.incorrect_answers,sv.next_review_at FROM student_vocabulary sv JOIN vocabulary v ON v.id=sv.vocabulary_id WHERE sv.student_id=:id ORDER BY CASE WHEN sv.status='learning' AND (sv.next_review_at IS NULL OR sv.next_review_at<=NOW()) THEN 0 WHEN sv.status='review' THEN 1 WHEN sv.status='learning' THEN 2 ELSE 3 END,sv.next_review_at NULLS FIRST,v.word");$stmt->execute(['id'=>$user['student_id']]);$rows=$stmt->fetchAll();$mastered=count(array_filter($rows,fn($r)=>$r['status']==='mastered'));$due=count(array_filter($rows,fn($r)=>in_array($r['status'],['learning','review'],true)&&(!$r['next_review_at']||strtotime($r['next_review_at'])<=time())));$average=$rows?array_sum(array_map(fn($r)=>(float)$r['mastery_score'],$rows))/count($rows):0;
$pageTitle='Meu vocabulário';$pageSubtitle='Palavras aprendidas, domínio e agenda de revisão.';require __DIR__.'/../../templates/header.php';?>
<section class="cards cards-3"><article class="card metric-card"><div><div class="label">Palavras acompanhadas</div><div class="metric"><?=count($rows)?></div><div class="metric-sub">Total do seu repertório</div></div><div class="metric-icon"><?=ui_icon('vocabulary')?></div></article><article class="card metric-card"><div><div class="label">Dominadas</div><div class="metric"><?=$mastered?></div><div class="metric-sub">Com status de domínio</div></div><div class="metric-icon"><?=ui_icon('sparkles')?></div></article><article class="card metric-card"><div><div class="label">Revisar agora</div><div class="metric"><?=$due?></div><div class="metric-sub">Domínio médio <?=number_format($average,0)?>%</div></div><div class="metric-icon"><?=ui_icon('plan')?></div></article></section>
<section class="panel"><div class="panel-head"><div><h2>Palavras acompanhadas</h2><p>O domínio é atualizado conforme seus acertos e revisões.</p></div></div><?php if(!$rows):?><div class="empty-state"><div class="empty-state-icon"><?=ui_icon('vocabulary')?></div><h3>Nenhuma palavra acompanhada</h3><p>Seu vocabulário será construído a partir das conversas e atividades.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Palavra</th><th>Tradução</th><th>Nível</th><th>Domínio</th><th>Status</th><th>Acertos</th><th>Próxima revisão</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($row['word'])?></strong><?php if($row['example']):?><div class="label"><?=e($row['example'])?></div><?php endif;?></td><td><?=e($row['translation']??'—')?></td><td><span class="badge <?=e(ui_level_class($row['level']))?>"><?=e($row['level']??'—')?></span></td><td style="min-width:150px"><div class="skill-head"><span><?=number_format((float)$row['mastery_score'],0)?>%</span></div><div class="progress slim"><span data-progress="<?=ui_percent($row['mastery_score'])?>"></span></div></td><td><span class="badge <?=e(ui_status_class($row['status']))?>"><?=e(ui_status_label($row['status']))?></span></td><td><?= (int)$row['correct_answers']?> / <?= (int)$row['incorrect_answers']?></td><td><?=e(ui_date($row['next_review_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php require __DIR__.'/../../templates/footer.php';?>
